cypress_script:
describe('Login Form', () => {
  it('should log in successfully with valid credentials', () => {
    cy.visit('https://the-internet.herokuapp.com/login');
    cy.get('#username').type('tomsmith');
    cy.get('#password').type('SuperSecretPassword!');
    cy.get('button.radius').click();
    cy.url().should('not.include', '/login');
  });

  it('should display error with invalid credentials', () => {
    cy.visit('https://the-internet.herokuapp.com/login');
    cy.get('#username').type('wronguser');
    cy.get('#password').type('wrongpassword');
    cy.get('button.radius').click();
    cy.url().should('include', '/login');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Login Form', () => {
  test('should log in successfully with valid credentials', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
    await page.fill('#username', 'tomsmith');
    await page.fill('#password', 'SuperSecretPassword!');
    await page.click('button.radius');
    await page.waitForURL('https://the-internet.herokuapp.com/secure');
  });

  test('should display error with invalid credentials', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
    await page.fill('#username', 'wronguser');
    await page.fill('#password', 'wrongpassword');
    await page.click('button.radius');
    await page.waitForURL('https://the-internet.herokuapp.com/login');
  });
});
